 62→// ── async-profiler download ────────────────────────────────────────────────
 63→
 64→tasks.register('downloadAsyncProfiler') {
 65→    description = 'Downloads and extracts the latest async-profiler release for the current OS/arch.'
 66→    group       = 'profiling'
 67→
 68→    def profilerDir = layout.buildDirectory.dir('async-profiler').get().asFile
 69→    outputs.dir(profilerDir)
 70→    onlyIf { !profilerDir.exists() || profilerDir.listFiles()?.length == 0 }
 71→
 72→    doLast {
 73→        def osName = System.getProperty('os.name').toLowerCase(Locale.ROOT)
 74→        def osArch = System.getProperty('os.arch').toLowerCase(Locale.ROOT)
 75→        def isLinux = osName.contains('linux')
 76→        def isMac   = osName.contains('mac') || osName.contains('darwin')
 77→
 78→        if (!isLinux && !isMac) {
 79→            throw new GradleException(
 80→                "async-profiler is not supported on this OS: ${System.getProperty('os.name')}. " +
 81→                "Profiling is only supported on Linux and macOS.")
 82→        }
 83→
 84→        def isArm = osArch.contains('aarch64') || osArch.contains('arm')
 85→        def platformSuffix = isMac ? 'macos' : (isArm ? 'linux-arm64' : 'linux-x64')
 86→
 87→        def conn = new URL('https://api.github.com/repos/async-profiler/async-profiler/releases/latest')
 88→                .openConnection() as HttpURLConnection
 89→        conn.setRequestProperty('Accept', 'application/vnd.github+json')
 90→        conn.setRequestProperty('User-Agent', 'jlsm-gradle-build')
 91→        conn.connectTimeout = 10_000
 92→        conn.readTimeout    = 15_000
 93→
 94→        if (conn.responseCode in [403, 429]) {
 95→            def retryAfter = conn.getHeaderField('Retry-After') ?: 'unknown'
 96→            throw new GradleException(
 97→                "GitHub API rate-limited (HTTP ${conn.responseCode}, Retry-After: ${retryAfter}). " +
 98→                "Manually extract an async-profiler release to: ${profilerDir.absolutePath}")
 99→        }
100→
101→        def json  = new groovy.json.JsonSlurper().parse(conn.inputStream)
102→        def asset = json.assets?.find { it.name ==~ /async-profiler-.*-${platformSuffix}\.tar\.gz/ }
103→
104→        if (asset == null) {
105→            throw new GradleException(
106→                "No asset found for '${platformSuffix}'. Available: ${json.assets?.collect { it.name }}")
107→        }
108→
109→        logger.lifecycle("Downloading async-profiler ${json.tag_name} for ${platformSuffix}...")
110→        def archive = new File(temporaryDir, asset.name as String)
111→        archive.parentFile.mkdirs()
112→        new URL(asset.browser_download_url as String).openStream().withCloseable { input ->
113→            java.nio.file.Files.copy(input, archive.toPath(),
114→                java.nio.file.StandardCopyOption.REPLACE_EXISTING)
115→        }
116→
117→        profilerDir.mkdirs()
118→        project.copy {
119→            from tarTree(archive)
120→            into profilerDir
121→            eachFile { details ->
122→                def parts = details.path.split('/', 2)
123→                if (parts.length == 2) { details.path = parts[1] } else { details.exclude() }
124→            }
125→            includeEmptyDirs = false
126→        }
127→
128→        logger.lifecycle("async-profiler extracted to ${profilerDir.absolutePath}")
129→    }
130→}
